"""Build a self-contained, static iOS requirements wireframe and coverage map."""
from pathlib import Path
import html
import json

ROOT = Path(__file__).parent
GROUPS = []
SCREENS = []


def group(key, title, description):
    GROUPS.append(dict(id=key, title=title, description=description))


def block(title, text='', kind=''):
    return f'<div class="block {kind}"><strong>{title}</strong><p>{text}</p></div>'


def rows(*items):
    return '<div class="rows">' + ''.join(f'<div>{x}</div>' for x in items) + '</div>'


def field(label, value):
    return f'<label class="field"><span>{label}</span><div>{value}</div></label>'


def chat(who, text, own=False):
    return f'<div class="bubble {"own" if own else ""}"><small>{who}</small><p>{text}</p></div>'


def screen(id, title, refs, state, entry, content, actions, note='', tab='日记'):
    SCREENS.append(dict(id=id, group=GROUPS[-1]['id'], title=title,
                        refs=refs.split(), state=state, entry=entry,
                        content=content, actions=actions, note=note, tab=tab))


