QUESTIONS = [
    ('A2','原位共用 Obsidian iOS vault 的后续兼容范围。','J01','今日正文和页内记录已确认；直接共用外部目录需另行验证。'),
    ('A3','首版是否要修改已经保存的日记正文？','D07','D07、D08、D09 为人工修订提案；AI 仍受限追加。'),
    ('A4','初次下载范围与录音保留是否合适？','A05','建议最近30天；录音原件由本人决定删除。'),
    ('A5','目标 iPhone、iOS 版本与中文长录音体验。','C05','先验证至少30分钟样本；不保证所有设备离线转写。'),
    ('A8','原模板、北极星定义与日常任务的配置位置。','J01','功能已确认必须保留；须逐项迁入本人原设置，示例不是实际配置。'),
    ('A7','个人资料进入 App 圆桌的选择与确认是否清楚？','F05','默认仅本问题，个人来源能力未验收前禁用。'),
]

REQ_TITLES = [
'打开即可记录','统一服务与按需身份','设置中启用同步','按场景说明智能权限','今日正文就是首页','阅读与 AI 区分','有范围的搜索','本地文件与附件',
'页内随手记','录音全过程','转写位置与能力','转写校正','可选 AI 整理','同页精确确认','同页保存状态','离线队列与未知结果',
'人工正文编辑提案','冲突与恢复','导师与独立问题','连续理解与依据','回答进度与失败','材料显式转交','问题长期保留','背景与版本',
'分享范围','参考辩论与控制','结果场次与恢复','独立 AI 日记保存','记忆与证据','纠正复核归档','遗忘范围','处理覆盖',
'权限入口','账号与服务状态','空间导出恢复','能力与渠道兼容',
'原模板完整保留','今日模板就地准备','整天的原记录方式','生成周报','生成月报','复盘校正保存回看','北极星指标版本','每日 MIT 与实际反馈','原日常自动化迁移']


def escape(value):
    return html.escape(str(value), quote=True)


def render_screen(item, position):
    actions = ''.join(f'<a href="#{target}" data-action-target="{target}">{escape(label)}<small>原型跳转 → {target}</small></a>' for label,target in item['actions'])
    mapping = ''.join(f'<tr><td>{escape(label)}</td><td><a href="#{target}">{target}</a></td></tr>' for label,target in item['actions'])
    tabs = ''.join(f'<a href="#{target}" class="{"active" if name == item["tab"] else ""}">{name}</a>' for name,target in [('日记','B01'),('导师','E01'),('记忆','G01')])
    phone_actions = '' if item.get('compact_note') else f'<div class="actions">{actions}</div>'
    permission = ''
    if item['tab'] == '记忆':
        permission = '<div class="permission">AI 权限 · 示例授权状态<br>历史：关 · 增量：开 · 整理：开 · 召回：开<br>接收方：DeepSeek API · Notes · 最近30天<br><a href="#H02">管理与撤回</a>　<a href="#G08">暂停 / 继续</a></div>'
    return f'''<article class="screen" id="{item['id']}" tabindex="-1" data-refs="{' '.join(item['refs'])}">
<p class="meta screen-flow-position"><span class="screen-id">{item['id']}</span>流程步骤 {position}</p><h3>{escape(item['title'])}</h3>
<p class="meta">来源：PRD v2.2-review · {' / '.join(item['refs'])}<br>入口：{escape(item['entry'])}<br>状态说明：{escape(item['state'])}</p>
<div class="phone" aria-label="{escape(item['title'])}的低保真页面">
<div class="system-bar"><span>9:41</span><span>信号　Wi-Fi　电量</span></div>
<div class="app-bar"><a href="#B02">☰ 日记</a><strong>9 月 12 日 ⌄</strong><a href="#H01">···</a></div>{permission}
<div class="phone-content">{item['content']}</div>
{phone_actions}<nav class="tabs" aria-label="示意 App 导航">{tabs}</nav></div>
<table aria-label="{item['id']} 操作与目标"><thead><tr><th>用户操作</th><th>目标状态</th></tr></thead><tbody>{mapping}</tbody></table>
{f'<p class="note">{escape(item["note"])}</p>' if item['note'] else ''}
<label class="feedback" for="note-{item['id']}">本屏意见 · 仅保存在当前浏览器<textarea id="note-{item['id']}" data-note-id="{item['id']}" placeholder="例如：这里还需要一个取消入口……"></textarea></label>
</article>'''


def build():
    ids = {item['id'] for item in SCREENS}
    assert len(ids) == len(SCREENS), 'Duplicate screen ID'
    for item in SCREENS:
        assert all(target in ids for _,target in item['actions']), item['id']
    required = {f'FR-{x:02d}' for x in range(1,len(REQ_TITLES)+1)}
    coverage = {key: [item['id'] for item in SCREENS if key in item['refs']] for key in sorted(required)}
    assert all(coverage.values()), 'Uncovered requirement'
    sections = []
    for flow in GROUPS:
        items = [item for item in SCREENS if item['group'] == flow['id']]
        sections.append(f'<section class="flow" id="{flow["id"]}"><div class="flow-head"><h2>{flow["title"]}</h2><a href="#index">回流程索引 ↑</a></div><p>{flow["description"]}</p><div class="screens">' + ''.join(render_screen(item, f'{GROUPS.index(flow)+1}.{i+1}') for i,item in enumerate(items)) + '</div></section>')
    coverage_rows = ''.join(f'<tr><td>{key} · {REQ_TITLES[int(key[3:])-1]}</td><td>' + ' · '.join(f'<a href="#{id}">{id}</a>' for id in value) + f'</td><td>{"待确认提案" if key == "FR-17" else "已呈现设计；尚未实现"}</td></tr>' for key,value in coverage.items())
    question_rows = ''.join(f'<tr><td>{id}</td><td>{escape(question)}</td><td><a href="#{target}">{target}</a> · {escape(default)}</td></tr>' for id,question,target,default in QUESTIONS)
    index = ''.join(f'<a href="#{g["id"]}">{g["title"]}</a>' for g in GROUPS)
    script = r'''
const KEY='riji-ios-wireframe-20260912-v2';
const status=document.getElementById('feedback-status');
let notes={};
try{notes=JSON.parse(localStorage.getItem(KEY)||'{}');}catch(e){status.textContent='本浏览器无法持久保存批注，请离开前导出。';}
for(const el of document.querySelectorAll('[data-note-id]')){
  el.value=notes[el.dataset.noteId]||'';
  el.addEventListener('input',()=>{notes[el.dataset.noteId]=el.value;try{localStorage.setItem(KEY,JSON.stringify(notes));status.textContent='批注已保存在当前浏览器';}catch(e){status.textContent='批注仅在本页内存中，请导出保存';}});
}
document.getElementById('export-notes').addEventListener('click',()=>{
 const lines=['# Riji iOS 低保真走查反馈','PRD v2.2-review · 2026-09-12',''];
 for(const [id,note] of Object.entries(notes)){if(note.trim())lines.push('## '+id,note.trim(),'');}
 if(lines.length===3)lines.push('尚无批注。');
 const blob=new Blob([lines.join('\n')],{type:'text/markdown;charset=utf-8'});
 const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='riji-ios-wireframe-feedback.md';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);
});
document.getElementById('print').addEventListener('click',()=>window.print());
'''
    document = f'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Riji iOS · 低保真全流程图 · 2026-09-12</title><style>{CSS}</style></head><body><main id="top"><header id="index"><p class="kicker">Riji / iOS · Product walkthrough draft</p><h1>打开，就是今天的日记</h1><p class="lead">直接看到正文，底部打字或录音，保存后仍在这一天。原模板、每日一件事、周报月报都保留；智能服务由产品统一提供，连接配置留给维护者。</p><p class="meta">依据：docs/PRD.md · v2.2-review · 2026-09-12。此图为拟议 iOS 体验，不是已运行产品。所有文字、日期与数量均为虚构示例。</p><div class="stats"><span><b>{len(SCREENS)}</b>界面与状态示意</span><span><b>{len(GROUPS)}</b>流程组</span><span><b>{len(REQ_TITLES)}</b>需求条目</span></div><p class="notice">所有手机按钮均为原型锚点，只跳到另一屏；不连接 Air、不调用 AI、不录音、不写日记。批注只留在当前浏览器，也可导出。黑白灰样式用于检查流程，不代表最终视觉设计。</p><p class="notice">先看常用体验：<a href="#B01">今日正文</a> → <a href="#C01">直接写一点</a> / <a href="#C03">录音</a> → <a href="#D03">仍在原页查看结果</a>。下面的多张图是同页状态与条件分支，不是让用户依次点击。<a href="#R01">周报月报</a>和<a href="#N01">北极星</a>从日记目录进入。</p><nav class="index" aria-label="完整流程索引">{index}</nav><div class="toolbar"><a href="#questions">先看待确认项</a><a href="#coverage">需求覆盖表</a><button id="export-notes" type="button">导出批注 Markdown</button><button id="print" type="button">打印 / 保存 PDF</button><span id="feedback-status">批注不会上传</span></div></header>{''.join(sections)}<section class="end-section" id="coverage"><h2>需求覆盖 · 每项都有页面或状态</h2><p class="muted">来源为主 PRD 第 4 节；此处核对设计覆盖，不代表功能已经开发或通过真机验收。</p><table class="coverage-table"><thead><tr><th>需求</th><th>页面 / 状态</th><th>覆盖情况</th></tr></thead><tbody>{coverage_rows}</tbody></table><h3>未适用与尚未启用的状态</h3><p>普通用户使用产品统一提供的服务，各账号资料独立；现有个人后端不代表多账户隔离已经完成。团队共享、支付、公开分享不在本轮范围。普通账号无服务器配对与相机扫码要求。远程通知为可选增强，不阻挡任务结果查询。直接编辑其他 App 的任意目录不在首版承诺内。个人资料进入圆桌、原始日记工具和新私聊自动记忆按后端真实能力启用。</p></section><section class="end-section" id="questions"><h2>待确认 · 可直接在对应屏留下意见</h2><table class="coverage-table"><thead><tr><th>ID</th><th>需要确定什么</th><th>当前提案与所在屏</th></tr></thead><tbody>{question_rows}</tbody></table><p class="print-note">本图不扩展生产数据授权。新的客户端、正文修订、产品账号隔离与个人来源分享，均须按新契约实现并验收。当前内部部署的真实 group_only 圆桌与本轮拟议 App 圆桌分开看待。</p><a href="#index">回到流程索引 ↑</a></section></main><a class="top-link" href="#index">索引 ↑</a><script>{script}</script></body></html>'''
    target = ROOT/'wireframe-riji-ios.html'
    target.write_text(document,encoding='utf-8')
    mapping = dict(prd='docs/PRD.md',version='2.2-review',date='2026-09-12',groups=GROUPS,coverage=coverage,
                   screens=[{key:value for key,value in item.items() if key != 'content'} for item in SCREENS])
    (ROOT/'flow-map.json').write_text(json.dumps(mapping,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    print(json.dumps(dict(screens=len(SCREENS),groups=len(GROUPS),requirements=len(coverage),bytes=target.stat().st_size),ensure_ascii=False))


if __name__ == '__main__':
    build()
